package com.backpack;

import com.google.gson.Gson;
import java.io.IOException;
import java.net.URI;
import java.util.Map;
import java.util.function.Consumer;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;

@Slf4j
final class BackpackApiClient
{
	private static final MediaType JSON_TYPE = MediaType.get("application/json; charset=utf-8");
	private final OkHttpClient http;
	private final Gson gson;
	private final BackpackConfig config;
	@Inject BackpackApiClient(OkHttpClient http, Gson gson, BackpackConfig config) { this.http = http; this.gson = gson; this.config = config; }

	void create(String base, String team, String player, Consumer<Session> success, Consumer<String> failure)
	{
		post(base, "/v1/teams/create", Map.of("name", team, "player", player), null, success, failure);
	}
	void join(String base, String code, String player, Consumer<Session> success, Consumer<String> failure)
	{
		post(base, "/v1/teams/join", Map.of("code", code, "player", player), null, success, failure);
	}
	void event(String base, String token, String type, long amount, long sequence)
	{
		post(base, "/v1/events", Map.of("type", type, "amount", amount, "sequence", sequence), token, ignored -> {}, error -> log.warn("Backpack sync event failed: {}", error));
	}
	private void post(String base, String path, Object payload, String token, Consumer<Session> success, Consumer<String> failure)
	{
		if (!validBase(base)) { failure.accept("Invalid server URL"); return; }
		Request.Builder builder = new Request.Builder().url(base.replaceAll("/$", "") + path).post(RequestBody.create(JSON_TYPE, gson.toJson(payload)));
		if (token != null) builder.header("Authorization", "Bearer " + token);
		if (!config.serverEnabled()) { failure.accept("Backpack server is disabled"); return; }
		http.newCall(builder.build()).enqueue(new Callback()
		{
			@Override public void onFailure(Call call, IOException e) { SwingUtilities.invokeLater(() -> failure.accept("Server unavailable")); }
			@Override public void onResponse(Call call, Response response)
			{
				try (Response ignored = response)
				{
					String body = response.body() == null ? "" : response.body().string();
					if (!response.isSuccessful()) { SwingUtilities.invokeLater(() -> failure.accept("Server returned " + response.code())); return; }
					Session session = gson.fromJson(body, Session.class); SwingUtilities.invokeLater(() -> success.accept(session));
				}
				catch (IOException | RuntimeException e) { SwingUtilities.invokeLater(() -> failure.accept("Invalid server response")); }
			}
		});
	}
	private static boolean validBase(String value)
	{
		try { URI uri = URI.create(value); return "https".equalsIgnoreCase(uri.getScheme()) || ("http".equalsIgnoreCase(uri.getScheme()) && ("localhost".equalsIgnoreCase(uri.getHost()) || "127.0.0.1".equals(uri.getHost()))); }
		catch (RuntimeException e) { return false; }
	}
	static final class Session { RemoteTeam team; String memberId; String token; }
	static final class RemoteTeam { String code; String name; Map<String, RemoteMember> members; }
	static final class RemoteMember { String id; String name; String role; long points; long xp; }
}

package com.backpack;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;

@ConfigGroup(BackpackConfig.GROUP)
public interface BackpackConfig extends Config
{
	String GROUP = "backpack";
	enum LevelNotifications
	{
		EVERY_LEVEL("Every level"), EVERY_TEN_LEVELS("Every 10 levels (20-90 and 99)");
		private final String label;
		LevelNotifications(String label) { this.label = label; }
		@Override public String toString() { return label; }
	}

	@Range(min = 1)
	@ConfigItem(
		keyName = "weeklyXpGoal",
		name = "Weekly team XP goal",
		description = "XP the team is trying to gain this week"
	)
	default int weeklyXpGoal()
	{
		return 500_000;
	}

	@ConfigItem(keyName = "serverEnabled", name = "Use Backpack server", description = "Sends your display name and XP, quest-point, and qualifying drop-value deltas to the configured Backpack server", warning = "This feature submits your IP address to a 3rd-party server not controlled or verified by RuneLite developers")
	default boolean serverEnabled() { return false; }

	@ConfigItem(keyName = "serverUrl", name = "Backpack server URL", description = "HTTPS URL of the Backpack server (localhost HTTP is allowed for development)")
	default String serverUrl() { return "https://flow-api-tmzl4.ondigitalocean.app"; }

	@ConfigItem(
		keyName = "discordEnabled",
		name = "Post to Discord",
		description = "Sends your display name and level-up or qualifying loot details to a Discord webhook",
		warning = "This feature submits your IP address to a 3rd-party server not controlled or verified by RuneLite developers"
	)
	default boolean discordEnabled()
	{
		return false;
	}

	@ConfigItem(
		keyName = "levelNotifications",
		name = "Level-up notifications",
		description = "Post every level-up or only levels 20, 30, 40, 50, 60, 70, 80, 90, and 99"
	)
	default LevelNotifications levelNotifications() { return LevelNotifications.EVERY_LEVEL; }

	@ConfigItem(
		keyName = "discordCollectionLog",
		name = "Collection Log notifications",
		description = "Post new Collection Log items to Discord"
	)
	default boolean discordCollectionLog() { return true; }

	@ConfigItem(
		keyName = "discordWebhookUrl",
		name = "Discord webhook URL",
		description = "A Discord channel webhook URL. It is stored in your RuneLite settings."
	)
	default String discordWebhookUrl()
	{
		return "";
	}

	@Range(min = 0)
	@ConfigItem(
		keyName = "discordDropValue",
		name = "Minimum drop value",
		description = "Only announce NPC loot worth at least this many coins"
	)
	default int discordDropValue()
	{
		return 1_000;
	}

	@ConfigItem(
		keyName = "discordDropScreenshot",
		name = "Attach Discord screenshots",
		description = "Attach a screenshot of the game frame to valuable-drop and Collection Log posts",
		warning = "Screenshots can contain chat messages or other private information"
	)
	default boolean discordDropScreenshot()
	{
		return true;
	}
}

