	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGGED_IN)
		{
			loadProfileState();
			resetRuntimeTracking();
			refreshPanel();
		}
		else if (event.getGameState() == GameState.LOGIN_SCREEN)
		{
			lastOverallXp = -1;
		}
	}

	@Subscribe
	public void onProfileChanged(ProfileChanged event)
	{
		loadProfileState();
		resetRuntimeTracking();
		refreshPanel();
	}

	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		Integer previousLevel = levels.put(event.getSkill(), event.getLevel());
		Integer previousSkillXp = skillXp.put(event.getSkill(), event.getXp());
		long overall = client.getOverallExperience();
		if (initializingTicks > 0)
		{
			return;
		}
		if (previousLevel != null && event.getLevel() > previousLevel && config.discordEnabled()
			&& shouldAnnounceLevel(config.levelNotifications(), event.getLevel()))
		{
			discord.send(config.discordWebhookUrl(), displayName() + " reached level " + event.getLevel() + " " + pretty(event.getSkill()) + "! 🎉");
		}
		if (!goalCompleted && personalGoal != null && personalGoal.getType() == Goal.Type.SKILL_XP
			&& event.getSkill().name().equals(personalGoal.getReference()) && previousSkillXp != null && event.getXp() > previousSkillXp)
		{
			goalProgress += event.getXp() - previousSkillXp;
			configManager.setRSProfileConfiguration(BackpackConfig.GROUP, GOAL_PROGRESS, goalProgress);
		}
		if (groupChallenge != null && !groupChallenge.isCooldown() && groupChallenge.getGoal().getType() == Goal.Type.SKILL_XP
			&& event.getSkill().name().equals(groupChallenge.getGoal().getReference()) && previousSkillXp != null && event.getXp() > previousSkillXp)
		{
			groupChallenge = groupChallenge.addProgress(event.getXp() - previousSkillXp);
			checkGroupChallenge();
			saveGroupChallenge();
		}
		if (lastOverallXp >= 0 && overall > lastOverallXp)
		{
			ensureCurrentWeek();
			state = state.addXp(overall - lastOverallXp);
			syncEvent("XP", overall - lastOverallXp);
			checkXpGoal();
			saveState();
			refreshPanel();
		}
		lastOverallXp = overall;
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (!config.discordEnabled() || !config.discordCollectionLog() || event.getType() != ChatMessageType.GAMEMESSAGE) return;
		Matcher matcher = COLLECTION_LOG_ITEM_PATTERN.matcher(Text.removeTags(event.getMessage()));
		if (!matcher.find()) return;
		String message = displayName() + " added " + matcher.group(1) + " to their Collection Log! 📚";
		if (config.discordDropScreenshot())
		{
			drawManager.requestNextFrameListener(image -> executor.execute(() ->
				discord.send(config.discordWebhookUrl(), message, ImageUtil.bufferedImageFromImage(image))));
		}
		else
		{
			discord.send(config.discordWebhookUrl(), message);
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (state != null && !state.isCurrentWeek(Instant.now()))
		{
			if (CarryPoints.total(state) > 0) badgeProgress = badgeProgress.carriedWeek();
			state = BackpackState.emptyForCurrentWeek(Instant.now());
			saveBadgeProgress(); saveState();
		}
		if (initializingTicks > 0 && --initializingTicks == 0)
		{
			lastOverallXp = client.getOverallExperience();
			lastQuestPoints = client.getVarpValue(VarPlayerID.QP);
			for (Skill skill : Skill.values())
			{
				if (skill != Skill.OVERALL)
				{
					levels.put(skill, client.getRealSkillLevel(skill));
					skillXp.put(skill, client.getSkillExperience(skill));
				}
			}
			refreshPanel();
		}
		if (initializingTicks == 0 && team != null)
		{
			if (groupChallenge == null || groupChallenge.cooldownFinished(Instant.now())) createGroupChallenge();
			refreshPanel();
		}
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		if (event.getVarpId() != VarPlayerID.QP || initializingTicks > 0) return;
		int current = event.getValue();
		if (lastQuestPoints >= 0 && current > lastQuestPoints)
		{
			state = state.addQuestPoints(current - lastQuestPoints);
			syncEvent("QUEST_POINTS", current - lastQuestPoints);
			if (!goalCompleted && personalGoal != null && personalGoal.getType() == Goal.Type.QUEST
				&& isSelectedQuestComplete())
			{
				completeGoal(CarryPoints.forQuestPoints((int) personalGoal.getTarget()));
			}
			if (groupChallenge != null && !groupChallenge.isCooldown() && groupChallenge.getGoal().getType() == Goal.Type.QUEST
				&& isQuestComplete(groupChallenge.getGoal()))
			{
				groupChallenge = groupChallenge.addProgress(groupChallenge.getGoal().getTarget());
				checkGroupChallenge(); saveGroupChallenge();
			}
			saveState();
			refreshPanel();
		}
		lastQuestPoints = current;
	}

	@Subscribe
	public void onServerNpcLoot(ServerNpcLoot event)
	{
		ItemStack best = null;
		long bestValue = 0;
		for (ItemStack item : event.getItems())
		{
			long value = itemManager.getItemPrice(item.getId()) * item.getQuantity();
			if (value > bestValue)
			{
				best = item;
				bestValue = value;
			}
		}
		if (best == null) return;
		if (groupChallenge != null && !groupChallenge.isCooldown() && groupChallenge.getGoal().getType() == Goal.Type.DROP
			&& Integer.toString(best.getId()).equals(groupChallenge.getGoal().getReference()))
		{
			groupChallenge = groupChallenge.addProgress(best.getQuantity());
			checkGroupChallenge(); saveGroupChallenge(); refreshPanel();
		}
		if (bestValue < config.discordDropValue()) return;

		ensureCurrentWeek();
		state = state.addDrop(bestValue);
		syncEvent("DROP", bestValue);
		String droppedItemName = itemManager.getItemComposition(best.getId()).getMembersName();
		if (!goalCompleted && personalGoal != null && personalGoal.getType() == Goal.Type.DROP
			&& Integer.toString(best.getId()).equals(personalGoal.getReference()) && best.getQuantity() >= personalGoal.getTarget())
		{
			completeGoal(CarryPoints.forDrop(bestValue));
		}
		saveState();
		refreshPanel();
		if (config.discordEnabled())
		{
			String itemName = itemManager.getItemComposition(best.getId()).getMembersName();
			String npcName = event.getComposition().getName();
			String message = displayName() + " got " + best.getQuantity() + " × " + itemName + " from " + npcName + " (" + bestValue + " gp)! 💰";
			if (config.discordDropScreenshot())
			{
				drawManager.requestNextFrameListener(image -> executor.execute(() ->
					discord.send(config.discordWebhookUrl(), message, ImageUtil.bufferedImageFromImage(image))));
			}
			else
			{
				discord.send(config.discordWebhookUrl(), message);
			}
		}
	}

	private void ensureCurrentWeek()
	{
		if (!state.isCurrentWeek(Instant.now()))
		{
			state = BackpackState.emptyForCurrentWeek(Instant.now());
		}
	}

	private void loadProfileState()
	{
		state = loadState();
		team = loadTeam();
		personalGoal = loadGoal();
		goalCompleted = loadGoalCompleted();
		goalProgress = loadGoalProgress();
		nextGoal = loadNextGoal();
		loadGroupChallenge();
		badgeProgress = loadBadgeProgress();
		serverToken = configManager.getRSProfileConfiguration(BackpackConfig.GROUP, SERVER_TOKEN);
		Long sequence = configManager.getRSProfileConfiguration(BackpackConfig.GROUP, SERVER_SEQUENCE, Long.class);
		serverSequence = sequence == null ? 0 : sequence;
	}

	private void resetRuntimeTracking()
	{
		lastOverallXp = -1;
		lastQuestPoints = -1;
		initializingTicks = client.getGameState() == GameState.LOGGED_IN ? 2 : 0;
		levels.clear();
		skillXp.clear();
		if (client.getGameState() == GameState.LOGGED_IN)
		{
			for (Skill skill : Skill.values())
			{
				if (skill != Skill.OVERALL)
				{
					levels.put(skill, client.getRealSkillLevel(skill));
					skillXp.put(skill, client.getSkillExperience(skill));
				}
			}
		}
	}

	private BackpackState loadState()
	{
		Long week = configManager.getRSProfileConfiguration(BackpackConfig.GROUP, WEEK_START, Long.class);
		Long xp = configManager.getRSProfileConfiguration(BackpackConfig.GROUP, XP_GAINED, Long.class);
		Integer drops = configManager.getRSProfileConfiguration(BackpackConfig.GROUP, DROPS_RECEIVED, Integer.class);
		Integer questPoints = configManager.getRSProfileConfiguration(BackpackConfig.GROUP, QUEST_POINTS_GAINED, Integer.class);
		Long dropPoints = configManager.getRSProfileConfiguration(BackpackConfig.GROUP, DROP_POINTS, Long.class);
		Long goalBonus = configManager.getRSProfileConfiguration(BackpackConfig.GROUP, GOAL_BONUS_POINTS, Long.class);
		BackpackState loaded = new BackpackState(week == null ? 0 : week, xp == null ? 0 : xp, 0, drops == null ? 0 : drops,
			questPoints == null ? 0 : questPoints, dropPoints == null ? 0 : dropPoints, goalBonus == null ? 0 : goalBonus);
		return loaded.isCurrentWeek(Instant.now()) ? loaded : BackpackState.emptyForCurrentWeek(Instant.now());
	}

	private void saveState()
	{
		if (state == null) return;
		configManager.setRSProfileConfiguration(BackpackConfig.GROUP, WEEK_START, state.getWeekStartEpoch());
		configManager.setRSProfileConfiguration(BackpackConfig.GROUP, XP_GAINED, state.getXpGained());
		configManager.setRSProfileConfiguration(BackpackConfig.GROUP, DROPS_RECEIVED, state.getDropsReceived());
		configManager.setRSProfileConfiguration(BackpackConfig.GROUP, QUEST_POINTS_GAINED, state.getQuestPointsGained());
		configManager.setRSProfileConfiguration(BackpackConfig.GROUP, DROP_POINTS, state.getDropPoints());
		configManager.setRSProfileConfiguration(BackpackConfig.GROUP, GOAL_BONUS_POINTS, state.getGoalBonusPoints());
		if (badgeProgress != null)
		{
			badgeProgress = badgeProgress.recordPoints(CarryPoints.total(state));
			saveBadgeProgress();
		}
	}

	private String displayName()
	{
		return client.getLocalPlayer() == null ? "A teammate" : client.getLocalPlayer().getName();
	}

	private static String pretty(Skill skill)
	{
		String lower = skill.name().toLowerCase().replace('_', ' ');
		return Character.toUpperCase(lower.charAt(0)) + lower.substring(1);
	}

	static boolean shouldAnnounceLevel(BackpackConfig.LevelNotifications mode, int level)
	{
		return mode == BackpackConfig.LevelNotifications.EVERY_LEVEL
			|| level == 99 || (level >= 20 && level <= 90 && level % 10 == 0);
	}

	private void refreshPanel()
	{
		if (panel == null || state == null) return;
		String username = client.getLocalPlayer() == null ? "You" : client.getLocalPlayer().getName();
		int combatLevel = client.getLocalPlayer() == null ? 0 : client.getLocalPlayer().getCombatLevel();
		SwingUtilities.invokeLater(() -> panel.update(team, username, state, config.weeklyXpGoal(), personalGoal, nextGoal,
			goalCompleted, groupChallenge, groupWins, combatLevel, badgeProgress));
	}

	@Override
	public void createTeam(String name)
	{
		if (config.serverEnabled())
		{
			api.create(config.serverUrl(), name, displayName(), this::applyServerSession, error -> panel.showError(error));
			return;
		}
		team = new Team(name, newInviteCode(), 1, true);
		saveTeam();
		clientThread.invokeLater(this::createGroupChallenge);
		refreshPanel();
	}

	@Override
	public void joinTeam(String code)
	{
		String normalized = code.toUpperCase().replaceAll("[^A-Z0-9]", "");
		if (normalized.length() != 8) return;
		if (config.serverEnabled())
		{
			api.join(config.serverUrl(), normalized, displayName(), this::applyServerSession, error -> panel.showError(error));
			return;
		}
		team = new Team("Joined team", normalized, 1, false);
		saveTeam();
		clientThread.invokeLater(this::createGroupChallenge);
		refreshPanel();
	}

	private void applyServerSession(BackpackApiClient.Session session)
	{
		if (session == null || session.team == null || session.token == null) { panel.showError("Invalid server session"); return; }
		BackpackApiClient.RemoteMember me = session.team.members == null ? null : session.team.members.get(session.memberId);
		team = new Team(session.team.name, session.team.code, session.team.members == null ? 1 : session.team.members.size(), me != null && "LEADER".equals(me.role));
		serverToken = session.token; serverSequence = 0;
		configManager.setRSProfileConfiguration(BackpackConfig.GROUP, SERVER_TOKEN, serverToken);
		configManager.setRSProfileConfiguration(BackpackConfig.GROUP, SERVER_MEMBER_ID, session.memberId);
		configManager.setRSProfileConfiguration(BackpackConfig.GROUP, SERVER_SEQUENCE, 0L);
		saveTeam(); refreshPanel(); clientThread.invokeLater(this::createGroupChallenge);
	}

	private void syncEvent(String type, long amount)
	{
		if (!config.serverEnabled() || serverToken == null || amount <= 0) return;
		serverSequence++;
		configManager.setRSProfileConfiguration(BackpackConfig.GROUP, SERVER_SEQUENCE, serverSequence);
		api.event(config.serverUrl(), serverToken, type, amount, serverSequence);
	}

	@Override
	public void leaveTeam()
	{
		team = null;
		groupChallenge = null;
		serverToken = null;
		serverSequence = 0;
		configManager.unsetRSProfileConfiguration(BackpackConfig.GROUP, TEAM_NAME);
		configManager.unsetRSProfileConfiguration(BackpackConfig.GROUP, TEAM_CODE);
		configManager.unsetRSProfileConfiguration(BackpackConfig.GROUP, TEAM_LEADER);
		configManager.unsetRSProfileConfiguration(BackpackConfig.GROUP, GROUP_CHALLENGE);
		configManager.unsetRSProfileConfiguration(BackpackConfig.GROUP, SERVER_TOKEN);
		configManager.unsetRSProfileConfiguration(BackpackConfig.GROUP, SERVER_MEMBER_ID);
		configManager.unsetRSProfileConfiguration(BackpackConfig.GROUP, SERVER_SEQUENCE);
		refreshPanel();
	}

	@Override
	public void resetWeek()
	{
		state = state.reset();
		goalCompleted = false;
		goalProgress = 0;
		configManager.setRSProfileConfiguration(BackpackConfig.GROUP, GOAL_COMPLETED, false);
		configManager.setRSProfileConfiguration(BackpackConfig.GROUP, GOAL_PROGRESS, 0);
		saveState();
		refreshPanel();
	}

	@Override
	public void setGoal(Goal goal)
	{
		nextGoal = null;
		configManager.unsetRSProfileConfiguration(BackpackConfig.GROUP, NEXT_GOAL);
		startGoal(goal);
	}

	private void startGoal(Goal goal)
	{
		personalGoal = goal;
		goalCompleted = false;
		goalProgress = 0;
		configManager.setRSProfileConfiguration(BackpackConfig.GROUP, PERSONAL_GOAL, goal.serialize());
		configManager.setRSProfileConfiguration(BackpackConfig.GROUP, GOAL_COMPLETED, false);
		configManager.setRSProfileConfiguration(BackpackConfig.GROUP, GOAL_PROGRESS, 0);
		refreshPanel();
	}

	@Override
	public void generateTask()
	{
		clientThread.invokeLater(() -> {
			TaskPlan plan = taskGenerator.generate();
			nextGoal = plan.getNext();
			if (nextGoal == null) configManager.unsetRSProfileConfiguration(BackpackConfig.GROUP, NEXT_GOAL);
			else configManager.setRSProfileConfiguration(BackpackConfig.GROUP, NEXT_GOAL, nextGoal.serialize());
			startGoal(plan.getCurrent());
		});
	}

	@Override
	public void clearGoal()
	{
		personalGoal = null;
		nextGoal = null;
		goalCompleted = false;
		goalProgress = 0;
		configManager.unsetRSProfileConfiguration(BackpackConfig.GROUP, PERSONAL_GOAL);
		configManager.unsetRSProfileConfiguration(BackpackConfig.GROUP, GOAL_COMPLETED);
		configManager.unsetRSProfileConfiguration(BackpackConfig.GROUP, GOAL_PROGRESS);
		configManager.unsetRSProfileConfiguration(BackpackConfig.GROUP, NEXT_GOAL);
		refreshPanel();
	}

	private Goal loadGoal()
	{
		return Goal.deserialize(configManager.getRSProfileConfiguration(BackpackConfig.GROUP, PERSONAL_GOAL));
	}

	private boolean loadGoalCompleted()
	{
		Boolean value = configManager.getRSProfileConfiguration(BackpackConfig.GROUP, GOAL_COMPLETED, Boolean.class);
		return value != null && value;
	}

	private long loadGoalProgress()
	{
		Long value = configManager.getRSProfileConfiguration(BackpackConfig.GROUP, GOAL_PROGRESS, Long.class);
		return value == null ? 0 : value;
	}

	private Goal loadNextGoal()
	{
		return Goal.deserialize(configManager.getRSProfileConfiguration(BackpackConfig.GROUP, NEXT_GOAL));
	}

	private boolean isSelectedQuestComplete()
	{
		return isQuestComplete(personalGoal);
	}

	private boolean isQuestComplete(Goal goal)
	{
		try { return net.runelite.api.Quest.valueOf(goal.getReference()).getState(client) == net.runelite.api.QuestState.FINISHED; }
		catch (RuntimeException ignored) { return false; }
	}

	private void createGroupChallenge()
	{
		if (team == null || client.getGameState() != GameState.LOGGED_IN) return;
		Goal goal = taskGenerator.generate().getCurrent();
		groupChallenge = new GroupChallenge(goal, 0, null, 0);
		saveGroupChallenge(); refreshPanel();
	}

	private void checkGroupChallenge()
	{
		if (groupChallenge == null || groupChallenge.isCooldown() || groupChallenge.getProgress() < groupChallenge.getGoal().getTarget()) return;
		groupChallenge = groupChallenge.wonBy(displayName(), Instant.now());
		groupWins++;
		badgeProgress = badgeProgress.groupWin();
		state = state.addGoalBonus(30);
		saveState();
		configManager.setRSProfileConfiguration(BackpackConfig.GROUP, GROUP_WINS, groupWins);
		saveBadgeProgress();
	}

	private void saveGroupChallenge()
	{
		if (groupChallenge != null) configManager.setRSProfileConfiguration(BackpackConfig.GROUP, GROUP_CHALLENGE, groupChallenge.serialize());
	}

	private void loadGroupChallenge()
	{
		groupChallenge = GroupChallenge.deserialize(configManager.getRSProfileConfiguration(BackpackConfig.GROUP, GROUP_CHALLENGE));
		Integer wins = configManager.getRSProfileConfiguration(BackpackConfig.GROUP, GROUP_WINS, Integer.class);
		groupWins = wins == null ? 0 : wins;
	}

	private void checkXpGoal()
	{
		if (!goalCompleted && personalGoal != null && personalGoal.getType() == Goal.Type.SKILL_XP
			&& goalProgress >= personalGoal.getTarget())
		{
			completeGoal(CarryPoints.forXp(personalGoal.getTarget()));
		}
	}

	private void completeGoal(long basePoints)
	{
		Goal.Type completedType = personalGoal.getType();
		state = state.addGoalBonus(CarryPoints.goalBonus(basePoints));
		badgeProgress = badgeProgress.complete(completedType).recordPoints(CarryPoints.total(state));
		saveBadgeProgress();
		if (nextGoal != null)
		{
			Goal followUp = nextGoal;
			nextGoal = null;
			configManager.unsetRSProfileConfiguration(BackpackConfig.GROUP, NEXT_GOAL);
			startGoal(followUp);
		}
		else
		{
			goalCompleted = true;
			configManager.setRSProfileConfiguration(BackpackConfig.GROUP, GOAL_COMPLETED, true);
		}
	}

	private BadgeProgress loadBadgeProgress()
	{
		return BadgeProgress.deserialize(configManager.getRSProfileConfiguration(BackpackConfig.GROUP, BADGE_PROGRESS));
	}

	private void saveBadgeProgress()
	{
		configManager.setRSProfileConfiguration(BackpackConfig.GROUP, BADGE_PROGRESS, badgeProgress.serialize());
	}

	private Team loadTeam()
	{
		String name = configManager.getRSProfileConfiguration(BackpackConfig.GROUP, TEAM_NAME);
		String code = configManager.getRSProfileConfiguration(BackpackConfig.GROUP, TEAM_CODE);
		Boolean leader = configManager.getRSProfileConfiguration(BackpackConfig.GROUP, TEAM_LEADER, Boolean.class);
		return name == null || code == null ? null : new Team(name, code, 1, leader != null && leader);
	}

	private void saveTeam()
	{
		configManager.setRSProfileConfiguration(BackpackConfig.GROUP, TEAM_NAME, team.getName());
		configManager.setRSProfileConfiguration(BackpackConfig.GROUP, TEAM_CODE, team.getCode());
		configManager.setRSProfileConfiguration(BackpackConfig.GROUP, TEAM_LEADER, team.isLeader());
	}

	private static String newInviteCode()
	{
		StringBuilder value = new StringBuilder(8);
		for (int i = 0; i < 8; i++) value.append(CODE_ALPHABET[RANDOM.nextInt(CODE_ALPHABET.length)]);
		return value.toString();
	}

	private static BufferedImage createIcon()
	{
		BufferedImage image = new BufferedImage(16, 16, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = image.createGraphics();
		g.setColor(new Color(126, 77, 42));
		g.fillRoundRect(3, 4, 10, 11, 3, 3);
		g.setColor(new Color(255, 184, 77));
		g.drawArc(5, 0, 6, 8, 0, 180);
		g.drawLine(3, 8, 13, 8);
		g.dispose();
		return image;
	}

	@Provides
	BackpackConfig provideConfig(ConfigManager manager)
	{
		return manager.getConfig(BackpackConfig.class);
	}
}

package com.backpack;

import java.time.DayOfWeek;
import java.time.Instant;
import java.time.ZoneOffset;
import java.time.ZonedDateTime;

final class BackpackState
{
	private final long weekStartEpoch;
	private final long xpGained;
	private final int questsCompleted;
	private final int dropsReceived;
	private final int questPointsGained;
	private final long dropPoints;
	private final long goalBonusPoints;

	BackpackState(long weekStartEpoch, long xpGained, int questsCompleted, int dropsReceived)
	{
		this(weekStartEpoch, xpGained, questsCompleted, dropsReceived, 0, 0, 0);
	}

	BackpackState(long weekStartEpoch, long xpGained, int questsCompleted, int dropsReceived,
		int questPointsGained, long dropPoints, long goalBonusPoints)
	{
		this.weekStartEpoch = weekStartEpoch;
		this.xpGained = Math.max(0, xpGained);
		this.questsCompleted = Math.max(0, questsCompleted);
		this.dropsReceived = Math.max(0, dropsReceived);
		this.questPointsGained = Math.max(0, questPointsGained);
		this.dropPoints = Math.max(0, dropPoints);
		this.goalBonusPoints = Math.max(0, goalBonusPoints);
	}

	static BackpackState emptyForCurrentWeek(Instant now)
	{
		return new BackpackState(startOfWeek(now), 0, 0, 0);
	}

	boolean isCurrentWeek(Instant now)
	{
		return weekStartEpoch == startOfWeek(now);
	}

	BackpackState addXp(long amount)
	{
		return new BackpackState(weekStartEpoch, xpGained + Math.max(0, amount), questsCompleted, dropsReceived, questPointsGained, dropPoints, goalBonusPoints);
	}

	BackpackState addDrop(long value)
	{
		return new BackpackState(weekStartEpoch, xpGained, questsCompleted, dropsReceived + 1, questPointsGained, dropPoints + CarryPoints.forDrop(value), goalBonusPoints);
	}

	BackpackState addQuestPoints(int amount)
	{
		return new BackpackState(weekStartEpoch, xpGained, questsCompleted + 1, dropsReceived, questPointsGained + Math.max(0, amount), dropPoints, goalBonusPoints);
	}

	BackpackState addGoalBonus(long points)
	{
		return new BackpackState(weekStartEpoch, xpGained, questsCompleted, dropsReceived, questPointsGained, dropPoints, goalBonusPoints + Math.max(0, points));
	}

	BackpackState reset()
	{
		return new BackpackState(weekStartEpoch, 0, 0, 0, 0, 0, 0);
	}

	long getWeekStartEpoch() { return weekStartEpoch; }
	long getXpGained() { return xpGained; }
	int getQuestsCompleted() { return questsCompleted; }
	int getDropsReceived() { return dropsReceived; }
	int getQuestPointsGained() { return questPointsGained; }
	long getDropPoints() { return dropPoints; }
	long getGoalBonusPoints() { return goalBonusPoints; }

	private static long startOfWeek(Instant instant)
	{
		ZonedDateTime utc = instant.atZone(ZoneOffset.UTC);
		return utc.with(DayOfWeek.MONDAY).toLocalDate().atStartOfDay(ZoneOffset.UTC).toEpochSecond();
	}
}

package com.backpack;

final class BadgeProgress
{
	private final int questTasks, skillTasks, dropTasks, groupWins, carrierWeeks;
	private final long bestWeeklyPoints;
	BadgeProgress(int questTasks, int skillTasks, int dropTasks, int groupWins, int carrierWeeks, long bestWeeklyPoints)
	{
		this.questTasks = Math.max(0, questTasks); this.skillTasks = Math.max(0, skillTasks);
		this.dropTasks = Math.max(0, dropTasks); this.groupWins = Math.max(0, groupWins);
		this.carrierWeeks = Math.max(0, carrierWeeks); this.bestWeeklyPoints = Math.max(0, bestWeeklyPoints);
	}
	static BadgeProgress empty() { return new BadgeProgress(0, 0, 0, 0, 0, 0); }
	BadgeProgress complete(Goal.Type type)
	{
		return new BadgeProgress(questTasks + (type == Goal.Type.QUEST ? 1 : 0), skillTasks + (type == Goal.Type.SKILL_XP ? 1 : 0),
			dropTasks + (type == Goal.Type.DROP ? 1 : 0), groupWins, carrierWeeks, bestWeeklyPoints);
	}
	BadgeProgress groupWin() { return new BadgeProgress(questTasks, skillTasks, dropTasks, groupWins + 1, carrierWeeks, bestWeeklyPoints); }
	BadgeProgress carriedWeek() { return new BadgeProgress(questTasks, skillTasks, dropTasks, groupWins, carrierWeeks + 1, bestWeeklyPoints); }
	BadgeProgress recordPoints(long points) { return new BadgeProgress(questTasks, skillTasks, dropTasks, groupWins, carrierWeeks, Math.max(bestWeeklyPoints, points)); }
	int getQuestTasks() { return questTasks; } int getSkillTasks() { return skillTasks; } int getDropTasks() { return dropTasks; }
	int getGroupWins() { return groupWins; } int getCarrierWeeks() { return carrierWeeks; }
	long getBestWeeklyPoints() { return bestWeeklyPoints; }
	int getTotalTasks() { return questTasks + skillTasks + dropTasks; }
	String serialize() { return questTasks + "," + skillTasks + "," + dropTasks + "," + groupWins + "," + carrierWeeks + "," + bestWeeklyPoints; }
	static BadgeProgress deserialize(String value)
	{
		if (value == null) return empty();
		try { String[] p = value.split(","); return new BadgeProgress(Integer.parseInt(p[0]), Integer.parseInt(p[1]), Integer.parseInt(p[2]), Integer.parseInt(p[3]), Integer.parseInt(p[4]), Long.parseLong(p[5])); }
		catch (RuntimeException ignored) { return empty(); }
	}
}

package com.backpack;

final class CarryPoints
{
	private CarryPoints() {}

	static long forXp(long xp)
	{
		return Math.max(0, xp) / 10_000;
	}

	static long forQuestPoints(int questPoints)
	{
		return Math.max(0, questPoints) * 5L;
	}

	static long forDrop(long value)
	{
		return Math.max(0, value) / 1_000_000 * 5L;
	}

	static long goalBonus(long basePoints)
	{
		return Math.min(50, Math.max(5, (long) Math.ceil(Math.max(0, basePoints) * 0.20d)));
	}

	static long total(BackpackState state)
	{
		return forXp(state.getXpGained()) + forQuestPoints(state.getQuestPointsGained())
			+ state.getDropPoints() + state.getGoalBonusPoints();
	}
}

package com.backpack;

import java.net.URI;
import java.net.URISyntaxException;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.MediaType;
import okhttp3.MultipartBody;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;
import java.io.IOException;
import java.io.ByteArrayOutputStream;
import java.awt.image.BufferedImage;
import javax.imageio.ImageIO;

@Slf4j
final class DiscordWebhookClient
{
	private static final MediaType JSON = MediaType.get("application/json; charset=utf-8");
	private final OkHttpClient httpClient;
	private final BackpackConfig config;

	@Inject
	DiscordWebhookClient(OkHttpClient httpClient, BackpackConfig config)
	{
		this.httpClient = httpClient;
		this.config = config;
	}

	void send(String webhookUrl, String message)
	{
		if (!isDiscordWebhook(webhookUrl))
		{
			log.warn("Backpack ignored an invalid Discord webhook URL");
			return;
		}

		String json = "{\"content\":\"" + escape(message) + "\",\"allowed_mentions\":{\"parse\":[]}}";
		Request request = new Request.Builder()
			.url(webhookUrl)
			.post(RequestBody.create(JSON, json))
			.build();
		if (!config.discordEnabled()) return;
		httpClient.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException exception)
			{
				log.warn("Unable to post Backpack event to Discord", exception);
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				try (Response ignored = response)
				{
					if (!response.isSuccessful())
					{
						log.warn("Discord webhook returned HTTP {}", response.code());
					}
				}
			}
		});
	}

	void send(String webhookUrl, String message, BufferedImage screenshot)
	{
		if (!isDiscordWebhook(webhookUrl))
		{
			log.warn("Backpack ignored an invalid Discord webhook URL");
			return;
		}
		try
		{
			ByteArrayOutputStream output = new ByteArrayOutputStream();
			ImageIO.write(screenshot, "png", output);
			String json = "{\"content\":\"" + escape(message) + "\",\"allowed_mentions\":{\"parse\":[]}}";
			RequestBody body = new MultipartBody.Builder()
				.setType(MultipartBody.FORM)
				.addFormDataPart("payload_json", json)
				.addFormDataPart("files[0]", "drop.png", RequestBody.create(MediaType.get("image/png"), output.toByteArray()))
				.build();
			enqueue(webhookUrl, body);
		}
		catch (IOException exception)
		{
			log.warn("Unable to encode Backpack screenshot", exception);
		}
	}

	private void enqueue(String webhookUrl, RequestBody body)
	{
		Request request = new Request.Builder().url(webhookUrl).post(body).build();
		if (!config.discordEnabled()) return;
		httpClient.newCall(request).enqueue(new Callback()
		{
			@Override public void onFailure(Call call, IOException exception) { log.warn("Unable to post Backpack event to Discord", exception); }
			@Override public void onResponse(Call call, Response response)
			{
				try (Response ignored = response)
				{
					if (!response.isSuccessful()) log.warn("Discord webhook returned HTTP {}", response.code());
				}
			}
		});
	}

	private static boolean isDiscordWebhook(String value)
	{
		if (value == null || value.length() > 2048) return false;
		try
		{
			URI uri = new URI(value);
			String host = uri.getHost();
			return "https".equalsIgnoreCase(uri.getScheme())
				&& ("discord.com".equalsIgnoreCase(host) || "discordapp.com".equalsIgnoreCase(host))
				&& uri.getPath() != null && uri.getPath().startsWith("/api/webhooks/");
		}
		catch (URISyntaxException ignored)
		{
			return false;
		}
	}

	private static String escape(String value)
	{
		return value.replace("\\", "\\\\").replace("\"", "\\\"").replace("\r", "").replace("\n", "\\n");
	}
}

package com.backpack;

import java.nio.charset.StandardCharsets;
import java.util.Base64;

final class Goal
{
	enum Type
	{
		SKILL_XP("⚔", "Skill XP"), DROP("💎", "Drop"), QUEST("📜", "Quest");

		private final String icon;
		private final String label;
		Type(String icon, String label) { this.icon = icon; this.label = label; }
		String getIcon() { return icon; }
		@Override public String toString() { return label; }
	}

	private final Type type;
	private final String detail;
	private final long target;
	private final String reference;

	Goal(Type type, String detail, long target)
	{
		this(type, detail, target, detail);
	}

	Goal(Type type, String detail, long target, String reference)
	{
		this.type = type;
		this.detail = detail;
		this.target = Math.max(1, target);
		this.reference = reference;
	}

	Type getType() { return type; }
	String getDetail() { return detail; }
	long getTarget() { return target; }
	String getReference() { return reference; }
	String getIcon() { return type.getIcon(); }

	String serialize()
	{
		return type.name() + ":" + Base64.getUrlEncoder().withoutPadding().encodeToString(detail.getBytes(StandardCharsets.UTF_8)) + ":" + target
			+ ":" + Base64.getUrlEncoder().withoutPadding().encodeToString(reference.getBytes(StandardCharsets.UTF_8));
	}

	static Goal deserialize(String value)
	{
		if (value == null) return null;
		try
		{
			String[] parts = value.split(":", 4);
			String detail = new String(Base64.getUrlDecoder().decode(parts[1]), StandardCharsets.UTF_8);
			String reference = parts.length == 4 ? new String(Base64.getUrlDecoder().decode(parts[3]), StandardCharsets.UTF_8) : detail;
			return new Goal(Type.valueOf(parts[0]), detail, Long.parseLong(parts[2]), reference);
		}
		catch (RuntimeException ignored)
		{
			return null;
		}
	}
}

package com.backpack;

import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Comparator;
import java.util.List;
import java.util.HashMap;
import java.util.Map;
import java.util.Locale;
import java.util.stream.Collectors;
import javax.inject.Inject;
import net.runelite.api.Quest;
import net.runelite.api.Skill;
import net.runelite.api.SpriteID;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.SkillIconManager;
import net.runelite.client.game.SpriteManager;
import net.runelite.http.api.item.ItemPrice;

final class GoalCatalog
{
	static final class Choice
	{
		private final String name;
		private final String reference;
		Choice(String name, String reference) { this.name = name; this.reference = reference; }
		String getName() { return name; }
		String getReference() { return reference; }
		@Override public String toString() { return name; }
	}

	private final ItemManager itemManager;
	private final SkillIconManager skillIconManager;
	private final SpriteManager spriteManager;
	private List<ItemPrice> items;
	private final Map<String, BufferedImage> badgeIcons = new HashMap<>();

	@Inject
	GoalCatalog(ItemManager itemManager, SkillIconManager skillIconManager, SpriteManager spriteManager)
	{
		this.itemManager = itemManager;
		this.skillIconManager = skillIconManager;
		this.spriteManager = spriteManager;
	}

	List<Choice> skills()
	{
		return Arrays.stream(Skill.values()).filter(skill -> skill != Skill.OVERALL)
			.map(skill -> new Choice(title(skill.name()), skill.name())).collect(Collectors.toList());
	}

	List<Choice> quests()
	{
		return Arrays.stream(Quest.values()).map(quest -> new Choice(quest.getName(), quest.name()))
			.sorted(Comparator.comparing(Choice::getName)).collect(Collectors.toList());
	}

	List<Choice> findItems(String query)
	{
		if (items == null || items.isEmpty()) items = new ArrayList<>(itemManager.search(""));
		String needle = query == null ? "" : query.trim().toLowerCase(Locale.ENGLISH);
		return items.stream().sorted(Comparator.comparingInt(item -> score(item.getName().toLowerCase(Locale.ENGLISH), needle)))
			.limit(30).map(item -> new Choice(item.getName(), Integer.toString(item.getId()))).collect(Collectors.toList());
	}

	BufferedImage icon(Goal goal)
	{
		try
		{
			switch (goal.getType())
			{
				case SKILL_XP: return skillIconManager.getSkillImage(Skill.valueOf(goal.getReference()));
				case DROP: return itemManager.getImage(Integer.parseInt(goal.getReference()));
				case QUEST: return skillIconManager.getSkillImage(Skill.MAGIC);
				default: return null;
			}
		}
		catch (RuntimeException ignored) { return null; }
	}

	BufferedImage badgeIcon(String key)
	{
		return badgeIcon(key, false);
	}

	BufferedImage badgeIcon(String key, boolean small)
	{
		String cacheKey = key + (small ? ":small" : ":large");
		if (badgeIcons.containsKey(cacheKey)) return badgeIcons.get(cacheKey);
		try
		{
			BufferedImage image;
			switch (key)
			{
				case "leader": image = skill(Skill.PRAYER, small); break;
				case "quest1": image = skill(Skill.MAGIC, small); break;
				case "quest5": image = skill(Skill.RUNECRAFT, small); break;
				case "quest20": image = skill(Skill.PRAYER, small); break;
				case "skill1": image = skill(Skill.ATTACK, small); break;
				case "skill5": image = skill(Skill.STRENGTH, small); break;
				case "skill20": image = skill(Skill.CONSTRUCTION, small); break;
				case "drop1": image = skill(Skill.MINING, small); break;
				case "drop5": image = skill(Skill.THIEVING, small); break;
				case "drop20": image = skill(Skill.SLAYER, small); break;
				case "goal5": image = skill(Skill.AGILITY, small); break;
				case "goal25": image = skill(Skill.FIREMAKING, small); break;
				case "group1": image = skill(Skill.SLAYER, small); break;
				case "group5": image = skill(Skill.ATTACK, small); break;
				case "carrier1": image = skill(Skill.AGILITY, small); break;
				case "carrier5": image = skill(Skill.HUNTER, small); break;
				case "points100": image = skill(Skill.RUNECRAFT, small); break;
				case "points500": image = skill(Skill.PRAYER, small); break;
				default: image = null;
			}
			if (image == null) image = fallbackBadgeIcon(key, small);
			if (image != null) badgeIcons.put(cacheKey, image);
			return image;
		}
		catch (RuntimeException ignored) { return fallbackBadgeIcon(key, small); }
	}

	private BufferedImage skill(Skill skill, boolean small)
	{
		return skillIconManager.getSkillImage(skill, small);
	}

	private BufferedImage fallbackBadgeIcon(String key, boolean small)
	{
		if (key.startsWith("drop")) return skill(Skill.MINING, small);
		if (key.startsWith("group")) return skill(Skill.SLAYER, small);
		if (key.startsWith("carrier")) return skill(Skill.AGILITY, small);
		if (key.startsWith("quest")) return skill(Skill.MAGIC, small);
		return skill(Skill.ATTACK, small);
	}

	private BufferedImage itemImage(String name)
	{
		for (Choice choice : findItems(name))
		{
			if (choice.getName().equalsIgnoreCase(name)) return itemManager.getImage(Integer.parseInt(choice.getReference()));
		}
		return null;
	}

	private static int score(String value, String query)
	{
		if (query.isEmpty()) return 0;
		if (value.equals(query)) return 0;
		if (value.startsWith(query)) return 1;
		if (value.contains(query)) return 2 + value.indexOf(query);
		return 100 + levenshtein(value, query);
	}

	private static int levenshtein(String a, String b)
	{
		int[] costs = new int[b.length() + 1];
		for (int j = 0; j <= b.length(); j++) costs[j] = j;
		for (int i = 1; i <= a.length(); i++)
		{
			int previous = costs[0]; costs[0] = i;
			for (int j = 1; j <= b.length(); j++)
			{
				int old = costs[j];
				costs[j] = Math.min(Math.min(costs[j] + 1, costs[j - 1] + 1), previous + (a.charAt(i - 1) == b.charAt(j - 1) ? 0 : 1));
				previous = old;
			}
		}
		return costs[b.length()];
	}

	private static String title(String value)
	{
		String lower = value.toLowerCase(Locale.ENGLISH).replace('_', ' ');
		return Character.toUpperCase(lower.charAt(0)) + lower.substring(1);
	}
}

package com.backpack;

import java.nio.charset.StandardCharsets;
import java.time.Instant;
import java.util.Base64;

final class GroupChallenge
{
	static final long COOLDOWN_SECONDS = 3_600;
	private final Goal goal;
	private final long progress;
	private final String winner;
	private final long cooldownUntil;

	GroupChallenge(Goal goal, long progress, String winner, long cooldownUntil)
	{
		this.goal = goal; this.progress = Math.max(0, progress); this.winner = winner; this.cooldownUntil = cooldownUntil;
	}
	Goal getGoal() { return goal; }
	long getProgress() { return progress; }
	String getWinner() { return winner; }
	boolean isCooldown() { return winner != null; }
	long remainingSeconds(Instant now) { return Math.max(0, cooldownUntil - now.getEpochSecond()); }
	boolean cooldownFinished(Instant now) { return isCooldown() && remainingSeconds(now) == 0; }
	GroupChallenge addProgress(long amount) { return new GroupChallenge(goal, progress + Math.max(0, amount), winner, cooldownUntil); }
	GroupChallenge wonBy(String name, Instant now) { return new GroupChallenge(goal, progress, name, now.getEpochSecond() + COOLDOWN_SECONDS); }

	String serialize()
	{
		String encodedGoal = Base64.getUrlEncoder().withoutPadding().encodeToString(goal.serialize().getBytes(StandardCharsets.UTF_8));
		String encodedWinner = winner == null ? "" : Base64.getUrlEncoder().withoutPadding().encodeToString(winner.getBytes(StandardCharsets.UTF_8));
		return encodedGoal + ":" + progress + ":" + encodedWinner + ":" + cooldownUntil;
	}
	static GroupChallenge deserialize(String value)
	{
		if (value == null) return null;
		try
		{
			String[] parts = value.split(":", -1);
			Goal goal = Goal.deserialize(new String(Base64.getUrlDecoder().decode(parts[0]), StandardCharsets.UTF_8));
			String winner = parts[2].isEmpty() ? null : new String(Base64.getUrlDecoder().decode(parts[2]), StandardCharsets.UTF_8);
			return goal == null ? null : new GroupChallenge(goal, Long.parseLong(parts[1]), winner, Long.parseLong(parts[3]));
		}
		catch (RuntimeException ignored) { return null; }
	}
}

package com.backpack;

import java.util.ArrayList;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ThreadLocalRandom;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Experience;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import net.runelite.api.Skill;

/** A deliberately conservative, expandable catalogue of useful quest routes. */
final class TaskGenerator
{
	private static final class Route
	{
		final String quest;
		final int combat;
		final Map<Skill, Integer> requirements = new EnumMap<>(Skill.class);
		Route(String quest, int combat, Object... values)
		{
			this.quest = quest; this.combat = combat;
			for (int i = 0; i < values.length; i += 2) requirements.put((Skill) values[i], (Integer) values[i + 1]);
		}
	}

	private static final Route[] ROUTES = {
		new Route("Witch's House", 20),
		new Route("Waterfall Quest", 25),
		new Route("The Knight's Sword", 10, Skill.MINING, 10),
		new Route("Elemental Workshop I", 20, Skill.MINING, 20, Skill.SMITHING, 20, Skill.CRAFTING, 20),
		new Route("Lost City", 40, Skill.CRAFTING, 31, Skill.WOODCUTTING, 36)
	};

	private final Client client;
	private final GoalCatalog catalog;
	@Inject TaskGenerator(Client client, GoalCatalog catalog) { this.client = client; this.catalog = catalog; }

	TaskPlan generate()
	{
		int combat = client.getLocalPlayer() == null ? 3 : client.getLocalPlayer().getCombatLevel();
		List<TaskPlan> exact = new ArrayList<>();
		List<TaskPlan> near = new ArrayList<>();
		for (Route route : ROUTES)
		{
			Quest quest = findQuest(route.quest);
			if (quest == null || quest.getState(client) == QuestState.FINISHED || combat + 5 < route.combat) continue;
			Skill missing = null; int gap = 0; boolean tooFar = false;
			for (Map.Entry<Skill, Integer> requirement : route.requirements.entrySet())
			{
				int difference = requirement.getValue() - client.getRealSkillLevel(requirement.getKey());
				if (difference > 0)
				{
					if (difference > 4 || missing != null) { tooFar = true; break; }
					missing = requirement.getKey(); gap = difference;
				}
			}
			Goal questGoal = new Goal(Goal.Type.QUEST, quest.getName(), 1, quest.name());
			if (!tooFar && missing == null) exact.add(new TaskPlan(questGoal, null));
			else if (!tooFar)
			{
				int targetLevel = client.getRealSkillLevel(missing) + gap;
				long xp = Math.max(1, Experience.getXpForLevel(targetLevel) - client.getSkillExperience(missing));
				near.add(new TaskPlan(new Goal(Goal.Type.SKILL_XP, pretty(missing) + " to level " + targetLevel, xp, missing.name()), questGoal));
			}
		}
		addDropTask(exact, combat, "Hill giant club", "Obor", 45, Skill.SLAYER, 1);
		addDropTask(exact, combat, "Bryophyta's essence", "Bryophyta", 55, Skill.SLAYER, 1);
		addDropTask(exact, combat, "Granite maul", "Gargoyle", 70, Skill.SLAYER, 75);
		addDropTask(exact, combat, "Dragon boots", "Spiritual mage", 85, Skill.SLAYER, 83);
		addDropTask(exact, combat, "Abyssal whip", "Abyssal demon", 95, Skill.SLAYER, 85);
		List<TaskPlan> choices = !near.isEmpty() ? near : exact;
		if (!choices.isEmpty()) return choices.get(ThreadLocalRandom.current().nextInt(choices.size()));
		Skill fallback = combat < 40 ? Skill.ATTACK : combat < 70 ? Skill.SLAYER : Skill.PRAYER;
		return new TaskPlan(new Goal(Goal.Type.SKILL_XP, pretty(fallback) + " training", 50_000, fallback.name()), null);
	}

	private void addDropTask(List<TaskPlan> tasks, int combat, String item, String monster, int requiredCombat, Skill skill, int requiredLevel)
	{
		if (combat < requiredCombat || client.getRealSkillLevel(skill) < requiredLevel) return;
		for (GoalCatalog.Choice choice : catalog.findItems(item))
		{
			if (choice.getName().equalsIgnoreCase(item))
			{
				tasks.add(new TaskPlan(new Goal(Goal.Type.DROP, item + " from " + monster, 1, choice.getReference()), null));
				return;
			}
		}
	}

	private Quest findQuest(String name)
	{
		for (Quest quest : Quest.values()) if (quest.getName().equalsIgnoreCase(name)) return quest;
		return null;
	}

	private static String pretty(Skill skill)
	{
		String value = skill.name().toLowerCase().replace('_', ' ');
		return Character.toUpperCase(value.charAt(0)) + value.substring(1);
	}
}

